using Flurl.Http;
using Serilog;
using WMS.CrossCuttingConcerns.Exceptions;
using WMS.CrossCuttingConcerns.FluentHTTP;

namespace WorkManagementSystem.Features.Publish.CommandHandler
{
    public class SignFileCommandHandler : ICommandHandler<SignFileCommand, string>
    {
        public async Task<string> ExecuteAsync(SignFileCommand command, CancellationToken ct)
        {
            if(command.TypeFile == 1)
            {
                var url = "https://demo.econtract.fpt.com/app/services/excall/api/excall";
                var r = new Random();
                var refId = r.Next(10000).ToString();
                var root1 = new FptInitializationContractSignByPosition
                {
                    id = "",
                    refId = refId,
                    selector = "flow_start_esc_create_auto_determine_econtract_integrate",
                    lookup = refId,
                    attrs = null,
                    payload = "HDLD",
                    body = new Body
                    {
                        alias = "",
                        refId = refId,
                        file = "",
                        fileName = "bien-ban-cuoc-hop-chi-bo_1501235210.docx",
                        docTypeCode = 2360,
                        headerFields = new List<HeaderField>
                    {
                        new HeaderField
                        {
                            id = "envName",
                            name = "Tên tài liệu",
                            type = "String",
                            value = "Hợp đồng xác định thời hạn 12 tháng (CT37)_05_05_2024"
                        },
                        new HeaderField
                        {
                            id = "envNo",
                            name = "Số tài liệu",
                            type = "String",
                            value = "CT37/2024/01"
                        },
                         new HeaderField
                        {
                            id = "envDate",
                            name = "Ngày hiệu lực",
                            type = "Date",
                            value = "2024-05-05"
                        },
                        new HeaderField
                        {
                            id = "envF00",
                            name = "Loại HĐLĐ/PLHĐLĐ",
                            type = "String",
                            value = "Hợp đồng xác định thời hạn 12 tháng"
                        }

                    },
                        parties = new List<Party>
                    {
                        new Party
                        {
                            id = "p_001",
                            isMyOrg = false,
                            isOrg = false,
                            orgName = "individual",
                            order = 1,
                            recipients = new List<Recipient>
                            {
                                new Recipient
                                {
                                    isEsign = true,
                                    recipientId = "p_001_r_001",
                                    email = "vansy9x@gmail.com",
                                    personalName = "Nguyễn Văn Sỹ",
                                    telephoneNumber = "0971489926",
                                    contactId = "4546888",
                                    role = "signer",
                                    order = 1,
                                    notifyTypes = new List<string> { "" },
                                    signTypes = new List<object>()
                                }
                            }
                        }
                    }
                    }
                };
                var token = await FptLogin();
                try
                {
                    var result = await FluentHTTPHelper<FptInitializationContractResponse>.PostAsyncWithBearerToken(url, token.access_token, null, root1);
                    return result.response.linkWebView;
                }
                catch (FlurlHttpTimeoutException timeout)
                {
                    Log.Debug("FlurlHttpTimeoutException:" + timeout.Message);
                    throw new FlurlHttpTimeOutDetail(url, timeout.Message);
                }
            }
            else
            {
                var url = command.FileUrl;
                var outputName = PdfSigner.AppendSuffixToFileName(command.FileName, "_signed");
                var outputDirectory = @"C:\Project\FileManagerService\Output\2023\file\signature";
                var outputFilePath = Path.Combine(outputDirectory, outputName);
                var signatureImage = Path.Combine(outputDirectory, "sign.png");
                // Tạo thư mục output nếu chưa tồn tại
                if (!Directory.Exists(outputDirectory))
                {
                    Directory.CreateDirectory(outputDirectory);
                }
                try
                {
                    await Task.Run(() => PdfSigner.InsertSignatureImage(url, outputFilePath, signatureImage));
                    return $"https://file-manager.digins.vn/Output/2023/file/signature/{outputName}";
                }
                catch (Exception ex)
                {
                    throw;
                }
            }
           
        }

        public async Task<FptLoginResponse> FptLogin()
        {
            var url = "https://demo.econtract.fpt.com/app/v1/client-auth/login";
           
            FptLoginRequest request = new FptLoginRequest
            {
                clientid = "fpt",
                clientsecret = "123456",
                username  = "contact@digins.vn",
                password = "g2c1yexp9Vl"
            };
            try
            {
                var result = await FluentHTTPHelper<FptLoginResponse>.PostAsync(url, null, request);
                return result;
            }
            catch (FlurlHttpTimeoutException timeout)
            {
                Log.Debug("FlurlHttpTimeoutException:" + timeout.Message);
                throw new FlurlHttpTimeOutDetail(url, timeout.Message);
            }
            catch (FlurlHttpException ex)
            {
                var error = await ex.GetResponseStringAsync();
                //  Log.Debug("FlurlHttpException:" + JsonConvert.SerializeObject(error));
                throw new FlurlHttpExceptionDetail(url, error);
            }
            catch (Exception ex)
            {
                Log.Debug("Exception:" + ex.Message);
                throw new Exception(ex.Message);
            }
        }
    }
}
